const canvas=document.querySelector('#signal'),ctx=canvas.getContext('2d'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches,frame=0,raf=0,w=1,h=1,mouse={x:0,y:0},visible=true;
const motion=document.querySelector('#motion');function syncMotion(){document.body.classList.toggle('paused',paused);motion.textContent=paused?'Play motion':'Pause motion';motion.setAttribute('aria-pressed',String(paused));motion.setAttribute('aria-label',paused?'Play animations':'Pause animations')}syncMotion();
const points=Array.from({length:190},(_,i)=>{const phi=Math.acos(1-2*(i+.5)/190),theta=Math.PI*(1+Math.sqrt(5))*i;return{x:Math.sin(phi)*Math.cos(theta),y:Math.cos(phi),z:Math.sin(phi)*Math.sin(theta)}});
function resize(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;const d=Math.min(devicePixelRatio,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);draw()}new ResizeObserver(resize).observe(canvas);
function draw(){ctx.clearRect(0,0,w,h);const t=frame*.0022,ry=t+mouse.x*.3,rx=.3+mouse.y*.2,r=Math.min(w,h)*.33,cx=w*.52,cy=h*.48;const projected=points.map(p=>{const x=p.x*Math.cos(ry)-p.z*Math.sin(ry),z=p.x*Math.sin(ry)+p.z*Math.cos(ry),y=p.y*Math.cos(rx)-z*Math.sin(rx),zz=p.y*Math.sin(rx)+z*Math.cos(rx);return{x:cx+x*r,y:cy+y*r,z:zz}});ctx.strokeStyle='#b8e56e';for(let i=0;i<points.length;i++){for(let j=i+1;j<points.length;j++){const a=points[i],b=points[j],dist=(a.x-b.x)**2+(a.y-b.y)**2+(a.z-b.z)**2;if(dist<.13){const p=projected[i],q=projected[j];ctx.globalAlpha=(p.z+q.z+2)*.08+.025;ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()}}}projected.sort((a,b)=>a.z-b.z).forEach(p=>{ctx.globalAlpha=(p.z+1)*.35+.2;ctx.fillStyle='#d5fa76';ctx.beginPath();ctx.arc(p.x,p.y,1.1+(p.z+1)*.55,0,Math.PI*2);ctx.fill()});ctx.globalAlpha=.25;ctx.strokeStyle='#d5fa76';ctx.lineWidth=.7;for(let k=0;k<3;k++){ctx.beginPath();ctx.ellipse(cx,cy,r*(1.23+k*.12),r*(.25+k*.06),t*.25+k*.85,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=1;ctx.fillStyle='#d5fa76';ctx.font='500 11px monospace';ctx.textAlign='center';ctx.fillText('S / S',cx,cy+4)}
function tick(){raf=0;if(paused||!visible||document.hidden)return;frame++;draw();raf=requestAnimationFrame(tick)}function start(){if(!raf&&!paused&&visible&&!document.hidden)raf=requestAnimationFrame(tick)}motion.addEventListener('click',()=>{paused=!paused;syncMotion();if(paused){cancelAnimationFrame(raf);raf=0;draw()}else start()});reduced.addEventListener('change',e=>{paused=e.matches;syncMotion();start()});document.addEventListener('visibilitychange',start);new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;start()}).observe(canvas);canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)/r.width-.5;mouse.y=(e.clientY-r.top)/r.height-.5;if(paused)draw()});start();
const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealObserver.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.project,.approach-grid,.eval-lab,.skill-grid,.timeline article').forEach(el=>{el.classList.add('reveal');revealObserver.observe(el)});
function progress(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=(max>0?scrollY/max*100:0)+'%'}addEventListener('scroll',progress,{passive:true});addEventListener('resize',progress);progress();
function time(){document.querySelector('#time').textContent=new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())+' IST'}time();setInterval(time,60000);
const checks={correctness:['The usual case works.','For [2, 4, 6], the result is 4. A useful review also checks the assumptions behind that success.'],clarity:['Make the contract explicit.','The function name is clear, but the input and output are undocumented. Explain that values must be a non-empty collection of numbers.'],robustness:['An empty list breaks it.','For [], len(values) is zero and the function raises ZeroDivisionError. Define the expected behavior and handle the empty input deliberately.']};document.querySelectorAll('.eval-button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.eval-button').forEach(x=>x.classList.toggle('active',x===b));const key=b.dataset.check;document.querySelector('#eval-label').textContent='CHECK / '+key.toUpperCase();document.querySelector('#eval-title').textContent=checks[key][0];document.querySelector('#eval-text').textContent=checks[key][1]}));
let proofStep=1;const days=[...document.querySelectorAll('.day')],proof=document.querySelector('#proof');proof.addEventListener('click',()=>{proofStep=proofStep>=3?1:proofStep+1;days.forEach((d,i)=>{d.classList.toggle('done',i<proofStep);d.classList.toggle('current',i===proofStep)});document.querySelector('#proof-status').textContent=proofStep===2?'Example: a working build is submitted as evidence.':proofStep===3?'Example: evidence verified. The next deliverable unlocks.':'Concept reset. Start with one deliverable.';proof.innerHTML=proofStep===3?'Restart the loop <span>↺</span>':'Continue the proof loop <span>→</span>'});
